/**
 * Placeholder picker — inserts a clicked placeholder into the target textarea.
 *
 * @module     report_discoursestats/placeholder_picker
 * @copyright  2026 Adam Jenkins <adam@wisecat.net>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define([],function(){"use strict";const insertAtCursor=(el,text)=>{const start=el.selectionStart??el.value.length;const end=el.selectionEnd??el.value.length;el.value=el.value.substring(0,start)+text+el.value.substring(end);el.selectionStart=el.selectionEnd=start+text.length;el.focus();};const init=()=>{document.querySelectorAll("details[data-placeholdertarget]").forEach(details=>{const targetId=details.dataset.placeholdertarget;const textarea=document.getElementById(targetId);if(!textarea){return;}details.querySelectorAll("code[data-insert]").forEach(code=>{code.style.cursor="pointer";code.title="Click to insert";code.addEventListener("click",()=>insertAtCursor(textarea,code.dataset.insert));});});};return{init:init};});
